import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

@DisplayName("80/71_symmetric_tree")
class SolutionTest {

    @Test
    void shouldDetectSymmetricTree() {

        Completed solution = new Completed();

        TreeNode root = new TreeNode(
            1,
            new TreeNode(2, new TreeNode(3), new TreeNode(4)),
            new TreeNode(2, new TreeNode(4), new TreeNode(3))
        );

        assertTrue(solution.isSymmetric(root));
    }

    @Test
    void shouldDetectAsymmetricTree() {

        Completed solution = new Completed();

        TreeNode root = new TreeNode(
            1,
            new TreeNode(2, null, new TreeNode(3)),
            new TreeNode(2, null, new TreeNode(3))
        );

        assertFalse(solution.isSymmetric(root));
    }

    @Test
    void shouldTreatEmptyTreeAsSymmetric() {

        Completed solution = new Completed();

        assertTrue(solution.isSymmetric(null));
    }

    @Test
    void shouldTreatSingleNodeAsSymmetric() {

        Completed solution = new Completed();

        assertTrue(solution.isSymmetric(new TreeNode(1)));
    }

    @Test
    void shouldDetectMirrorWithUnevenStructure() {

        Completed solution = new Completed();

        TreeNode root = new TreeNode(
            1,
            new TreeNode(2, new TreeNode(3), null),
            new TreeNode(2, null, new TreeNode(3))
        );

        assertTrue(solution.isSymmetric(root));
    }
